using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
public partial class MigrationScene {
 readonly Dictionary<string,(string Attack,double Hp,bool Alert)> enemyCueState=new();readonly List<(AudioStreamPlayer3D Node,double Until)> enemySounds=new();readonly Dictionary<int,AudioStreamWav> enemyCueClips=new();double enemyCueDue;
 AudioStreamWav EnemyCue(int kind){if(enemyCueClips.TryGetValue(kind,out var clip))return clip;if(kind==3)return enemyCueClips[kind]=Tone(1,.18);const int rate=22050;double duration=kind==0?.7:kind==1?.38:.18;int count=(int)(duration*rate);var data=new byte[count*2];var random=new Random(341+kind);double low=0;for(int i=0;i<count;i++){double t=i/(double)rate;low=low*.85+(random.NextDouble()*2-1)*.15;double envelope=Math.Sin(t/duration*Math.PI);double sample=kind==2?low*Math.Exp(-t*18):Math.Sin(t*(kind==0?75+20*t:135-100*t)*Math.PI*2)*.25+low*.55;short v=(short)(Math.Clamp(sample*envelope,-1,1)*18000);data[i*2]=(byte)v;data[i*2+1]=(byte)(v>>8);}return enemyCueClips[kind]=new(){Format=AudioStreamWav.FormatEnum.Format16Bits,MixRate=rate,Data=data};}
 void EnemySound(Vector3 at,int kind){if(muted||testing||DisplayServer.GetName()=="headless"||enemySounds.Count>=8||Distance(player.Position,at)>32)return;var sound=new AudioStreamPlayer3D{Position=at+Vector3.Up*(kind>=4?.55f:1.3f),Stream=kind>=4?DogCue(kind==5):EnemyCue(kind),MaxDistance=35,UnitSize=5,VolumeDb=-9};AddChild(sound);sound.Play();enemySounds.Add((sound,Time.GetTicksMsec()/1000.0+1));}
 void DrawEnemyCues(){double now=Time.GetTicksMsec()/1000.0;for(int i=enemySounds.Count-1;i>=0;i--)if(now>enemySounds[i].Until){enemySounds[i].Node.QueueFree();enemySounds.RemoveAt(i);}if(now<enemyCueDue)return;enemyCueDue=now+.08;var ids=new HashSet<string>();foreach(var e in infected){if(IsCheckpointGuard(e.Id)||IsMillBoss(e.Id)||Species(e.Id)!=""&&Species(e.Id)!="dog")continue;ids.Add(e.Id);bool alert=e.Memory>0;enemyCueState.TryGetValue(e.Id,out var previous);if(Species(e.Id)=="dog"){if(e.AttackState=="dog-windup"&&previous.Attack!="dog-windup")EnemySound(e.Body.Position,5);else if(alert&&!previous.Alert)EnemySound(e.Body.Position,4);enemyCueState[e.Id]=(e.AttackState,e.Hp,alert);continue;}if(e.AttackState=="windup"&&previous.Attack!="windup")EnemySound(e.Body.Position,1);else if(previous.Hp>0&&e.Hp<previous.Hp)EnemySound(e.Body.Position,2);else if(alert&&!previous.Alert)EnemySound(e.Body.Position,0);enemyCueState[e.Id]=(e.AttackState,e.Hp,alert);if(CoopClient)AnimateCharacter(e);}foreach(var id in enemyCueState.Keys.ToArray())if(!ids.Contains(id))enemyCueState.Remove(id);foreach(var sound in enemySounds)sound.Node.StreamPaused=muted;}
}
